// A capture's means may differ from the blend by this much (game units).
constexpr float TOLERANCE = 0.03f;
constexpr int STATS = 9;

// The three shapes the pad position blends, their weights, and whether the
// class's kept rows apply.
struct Weights {
    int shape[3];
    float w[3];
    bool kept;
};

// The nine numbers of a capture: per-draw vertex positions, `draws` draws of
// `verts[d]` vertices each. False for an empty capture.
inline bool Stats(const float (*pos)[handweld::MAX_VERTS][3], const unsigned* verts, int draws,
                  float out[STATS]) {
    if (draws <= 0)
        return false;
    double all[3] = {0, 0, 0};
    double first[3] = {0, 0, 0}, last[3] = {0, 0, 0};
    unsigned total = 0;
    for (int d = 0; d < draws; d++) {
        if (verts[d] == 0 || verts[d] > (unsigned)handweld::MAX_VERTS)
            return false;
        for (unsigned v = 0; v < verts[d]; v++)
            for (int a = 0; a < 3; a++) {
                const double c = pos[d][v][a];
                all[a] += c;
                if (d == 0)
                    first[a] += c;
                if (d == draws - 1)
                    last[a] += c;
            }
        total += verts[d];
    }
    for (int a = 0; a < 3; a++) {
        out[a] = (float)(all[a] / total);
        out[3 + a] = (float)(first[a] / verts[0]);
        out[6 + a] = (float)(last[a] / verts[draws - 1]);
    }
    return true;
}

inline const float (*Rows(int side, int class_id, bool kept))[STATS] {
    if (kept && class_id == HAND_REF_KEPT_CLASS)
        return HAND_REF_KEPT[side];
    return HAND_REF[side][class_id];
}

// The reference nine numbers for a class and pad blend.
inline void Expected(int side, int class_id, const Weights& wt, float out[STATS]) {
    const float(*rows)[STATS] = Rows(side, class_id, wt.kept);
    for (int i = 0; i < STATS; i++) {
        out[i] = 0.0f;
        for (int n = 0; n < 3; n++)
            out[i] += wt.w[n] * rows[wt.shape[n]][i];
    }
}

// The largest distance, over the three reference points, between a capture
// and the reference.
inline float Error(const float got[STATS], const float want[STATS]) {
    float worst = 0.0f;
    for (int j = 0; j < STATS; j += 3) {
        const float dx = got[j] - want[j], dy = got[j + 1] - want[j + 1], dz = got[j + 2] - want[j + 2];
        const float d = std::sqrt(dx * dx + dy * dy + dz * dz);
        if (d > worst)
            worst = d;
    }
    return worst;
}

// Without the pad position: how far a capture lies outside the range the
// class's seven shapes span, per component (0 when inside; the kept rows
// count as shapes of the class).
inline float OutsideClassRange(int side, int class_id, const float got[STATS]) {
    float worst = 0.0f;
    for (int i = 0; i < STATS; i++) {
        float lo = HAND_REF[side][class_id][0][i], hi = lo;
        for (int s = 0; s < 7; s++) {
            const float v = HAND_REF[side][class_id][s][i];
            if (v < lo) lo = v;
            if (v > hi) hi = v;
            if (class_id == HAND_REF_KEPT_CLASS) {
                const float k = HAND_REF_KEPT[side][s][i];
                if (k < lo) lo = k;
                if (k > hi) hi = k;
            }
        }
        const float out = got[i] < lo ? lo - got[i] : got[i] > hi ? got[i] - hi : 0.0f;
        if (out > worst)
            worst = out;
    }
    return worst;
}

